import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.C-si7TFR.js";const f=JSON.parse('{"title":"Create, version and troubleshoot workflows","description":"","frontmatter":{"title":"Create, version and troubleshoot workflows"},"headers":[],"relativePath":"guide/workflows.md","filePath":"guide/workflows.md"}'),i={name:"guide/workflows.md"};function r(s,e,l,d,c,u){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="create-version-and-troubleshoot-workflows" tabindex="-1">Create, version and troubleshoot workflows <a class="header-anchor" href="#create-version-and-troubleshoot-workflows" aria-label="Permalink to &quot;Create, version and troubleshoot workflows&quot;">​</a></h1><h2 id="start-with-an-explicit-flow" tabindex="-1">Start with an explicit flow <a class="header-anchor" href="#start-with-an-explicit-flow" aria-label="Permalink to &quot;Start with an explicit flow&quot;">​</a></h2><ol><li>In workflow mode, select <strong>New</strong> and add a manual trigger.</li><li>Choose logic, tool or AI nodes from the node menu and connect the execution path.</li><li>Configure inputs and outputs for each node, save and execute manually.</li><li>Inspect execution records before adding a schedule or API trigger.</li></ol><p>A <a href="./../trigger_start.html">manual trigger</a> is suited to debugging. Sync and async APIs have distinct call and response behavior and are not interchangeable.</p><h2 id="let-an-agent-create-or-modify-a-flow" tabindex="-1">Let an agent create or modify a flow <a class="header-anchor" href="#let-an-agent-create-or-modify-a-flow" aria-label="Permalink to &quot;Let an agent create or modify a flow&quot;">​</a></h2><ol><li>Describe the goal, inputs, processing steps and expected output in a conversation.</li><li>If <strong>Add workflow</strong> is displayed, create the entry before asking the agent to generate a flow.</li><li>Inspect the workflow preview and result. Use <strong>Open workflow</strong> to enter the canvas when available.</li><li>For changes, inspect the <strong>before/after diff</strong> instead of relying on a textual “modified” response.</li><li>Save, then inspect the version and manual execution result.</li></ol><p>A workflow tool calls an enabled API workflow; it is not the same as agent-assisted creation or editing.</p><h2 id="debug-and-manage-versions" tabindex="-1">Debug and manage versions <a class="header-anchor" href="#debug-and-manage-versions" aria-label="Permalink to &quot;Debug and manage versions&quot;">​</a></h2><ul><li>Run debugging from the agent conversation or canvas and inspect failed nodes, inputs and errors.</li><li>Use the version entry to inspect changes and compare versions. Before rollback, check the target version and current unsaved work.</li><li>Rolling back a version does not delete execution history or undo side effects in external systems.</li></ul><h2 id="execution-records-and-ai-diagnosis" tabindex="-1">Execution records and AI diagnosis <a class="header-anchor" href="#execution-records-and-ai-diagnosis" aria-label="Permalink to &quot;Execution records and AI diagnosis&quot;">​</a></h2><ol><li>Open the target workflow&#39;s execution records and select a failed run.</li><li>Inspect node status, errors, retries and associated traces.</li><li>When the failed execution offers AI diagnosis, use it to assist analysis; diagnosis is not automatic repair.</li><li>Return to the canvas, fix the flow and manually verify it again.</li></ol><p>Logs and diagnosis context can contain credentials, prompts, business data and external endpoints. Redact before sharing. A visible diagnosis entry does not guarantee that a model is available.</p><h2 id="execute-safely" tabindex="-1">Execute safely <a class="header-anchor" href="#execute-safely" aria-label="Permalink to &quot;Execute safely&quot;">​</a></h2><p>External requests, SSH, file and script nodes interact with real systems. Restrict destinations, directories and credentials; bind parameters and never concatenate user input into commands or SQL. Debug with no-side-effect data before enabling unattended triggers.</p>',14)])])}const g=a(i,[["render",r]]);export{f as __pageData,g as default};
